public class ElevatorMech {
    public void setTargetHeight(double meters) { /* sends the order */ }
    public double getHeight()                  { /* reads the sensor */ return 0.0; }
}

public class ElevatorSubsystem extends MwSubsystem<ElevatorStates, ElevatorConstants> {
    private final ElevatorMech elevator = new ElevatorMech();

    @Override
    public void updateLogic(double timestamp) {
        if (OI.getRaiseButton()) {
            elevator.setTargetHeight(1.2);
        } else {
            elevator.setTargetHeight(0.0);
        }
    }
}

public class RobotContainer extends SubsystemManager {
    public RobotContainer() {
        super(BuildConstants.class);
        registerSubsystem(ElevatorSubsystem.getInstance());
        registerSubsystem(IntakeSubsystem.getInstance());
    }
}
